import assert from 'node:assert/strict';
import { readFileSync, writeFileSync } from 'node:fs';
import { assessWithRetry, configuration, feedbackVersion } from '../server/services';
try { process.loadEnvFile('.env'); } catch {}
const production = process.argv.includes('--production');
const all = JSON.parse(readFileSync('tmp/feedback-luna-rollout-cases.json', 'utf8'));
const cases = production ? all.filter(c => ['gift_complete_four_criteria', 'b1_cloze_correct_inversion_unchanged', 'b1_cloze_meaning_met_inversion_wrong', 'a2_repeated_inability_is_not_reason', 'a2_missing_alternative_and_availability_placeholders'].includes(c.name)) : all;
const bank = JSON.parse(readFileSync('content/catalogue.json', 'utf8'));
assert.equal(configuration().feedback_model, 'gpt-6-luna');
const report:any = { created_at: new Date().toISOString(), production, model: configuration().feedback_model, feedback_version: feedbackVersion, calls: 0, runs: [] };
const path = 'tmp/feedback-luna-rollout-' + (production ? 'production' : 'live') + '.json';
const save = () => writeFileSync(path, JSON.stringify(report, null, 2) + '\n');
const origin='https://oefenschrift.nl';
let cookie='';
if (production) {
 const response=await fetch(origin+'/api/status');
 assert.ok(response.ok);
 assert.equal((await response.json()).feedback,true);
 cookie=response.headers.getSetCookie().map(value=>value.split(';')[0]).join('; ');
 assert.ok(cookie);
}
for (const c of cases) {
 const item=bank.find(i=>i.id===c.item);
 assert.ok(item,c.item);
 assert.equal(item.criteria.length,c.expected_met.length);
 const began=performance.now();
 const row:any={...c, attempts:[]};
 try {
  let result;
  if (production) {
   report.calls++;
   const response=await fetch(origin+'/api/feedback', {method:'POST',headers:{'Content-Type':'application/json',Origin:origin,Cookie:cookie},body:JSON.stringify({id:item.id,answer:c.answer,lang:'nl',speech_confirmed:true})});
   result=await response.json();
   row.http_status=response.status;
   assert.equal(response.status,200,JSON.stringify({status:response.status,code:result.code}));
   assert.equal(result.feedback_version,feedbackVersion);
  } else {
   result=await assessWithRetry(item,c.answer,async(url,init)=>{
    const sent=JSON.parse(init!.body as string);
    assert.equal(sent.model,'gpt-6-luna');
    assert.deepEqual(sent.reasoning,{effort:'none'});
    report.calls++;
    const response=await fetch(url,init);
    const raw=await response.clone().json();
    row.attempts.push({status:response.status, provider_model:raw.model, usage:raw.usage, raw_result:response.ok?raw.output?.flatMap(o=>o.content||[]).filter(x=>x.type==='output_text').map(x=>x.text).join(''):undefined, error:response.ok?undefined:{code:raw.error?.code,type:raw.error?.type,param:raw.error?.param}});
    return response;
   });
  }
  row.result=result;
  assert.equal(result.model,'gpt-6-luna');
  assert.deepEqual(result.criteria.map(x=>x.met),c.expected_met);
  assert.deepEqual(result.criteria.map(x=>x.index),item.criteria.map((_,i)=>i));
  assert.ok(result.criteria.every(x=>!x.evidence||c.answer.includes(x.evidence)));
  for(const fact of c.must_preserve) assert.ok(result.corrected_text.includes(fact), 'missing fact: '+fact);
  for(const fact of c.forbidden_additions) assert.ok(!result.corrected_text.toLowerCase().includes(fact.toLowerCase()), 'added fact: '+fact);
  if(c.name.includes('cloze')&&c.expected_met[0]) assert.doesNotMatch(result.corrected_text,/\[|\]/);
  if(c.expected_corrected_text) assert.equal(result.corrected_text,c.expected_corrected_text);
  if(c.name==='off_task_prompt_injection') assert.equal(result.on_task,false);
  row.passed=true;
 } catch(error:any) {
  row.passed=false;
  row.error={name:error.name, message:error.message,reason:error.reason};
 }
 row.seconds=Math.round((performance.now()-began)/10)/100;
 report.runs.push(row); save();
 console.log(JSON.stringify({name:c.name,passed:row.passed,attempts:row.attempts.length,seconds:row.seconds,error:row.error}));
}
assert.ok(report.runs.every(x=>x.passed), 'One or more rollout cases failed.');
